/** Convert one BuildRequest into the NAPI transport shape. */
export function toNapiBuildRequest(value: BuildRequest): Napi.BuildRequest {
    if (value.kind === "module") {
        return {
            kind: "module",
            module: toNapiModule(value.module),
            target: toNapiTargetId(value.target),
            output: toNapiModuleBuildKind(value.output),
        };
    }

    if (value.kind === "build") {
        return {
            kind: "build",
            target: toNapiTargetId(value.target),
        };
    }

    if (value.kind === "target") {
        return {
            kind: "target",
            target: toNapiTargetId(value.target),
        };
    }

    if (value.kind === "product") {
        return {
            kind: "product",
            product: toNapiProductId(value.product),
        };
    }

    throw new Error("unknown BuildRequest");
}

/** Convert one NAPI BuildOutput into the public bridge shape. */
export function fromNapiBuildOutput(value: Napi.BuildOutput): BuildOutput {
    if (value.kind === "script") {
        const payload_version = value.version;
        if (payload_version == null) {
            throw new Error("version payload is missing");
        }

        const payload_script = value.script;
        if (payload_script == null) {
            throw new Error("script payload is missing");
        }

        return {
            kind: "script",
            version: fromNapiArtifactVersion(payload_version),
            script: fromNapiScript(payload_script),
        };
    }

    if (value.kind === "object") {
        const payload_version = value.version;
        if (payload_version == null) {
            throw new Error("version payload is missing");
        }

        const payload_object = value.object;
        if (payload_object == null) {
            throw new Error("object payload is missing");
        }

        return {
            kind: "object",
            version: fromNapiArtifactVersion(payload_version),
            object: fromNapiObject(payload_object),
        };
    }

    if (value.kind === "asset") {
        const payload_version = value.version;
        if (payload_version == null) {
            throw new Error("version payload is missing");
        }

        const payload_asset = value.asset;
        if (payload_asset == null) {
            throw new Error("asset payload is missing");
        }

        return {
            kind: "asset",
            version: fromNapiArtifactVersion(payload_version),
            asset: fromNapiAsset(payload_asset),
        };
    }

    if (value.kind === "build") {
        const payload_version = value.version;
        if (payload_version == null) {
            throw new Error("version payload is missing");
        }

        const payload_build = value.build;
        if (payload_build == null) {
            throw new Error("build payload is missing");
        }

        return {
            kind: "build",
            version: fromNapiArtifactVersion(payload_version),
            build: fromNapiBuild(payload_build),
        };
    }

    if (value.kind === "bundle") {
        const payload_version = value.version;
        if (payload_version == null) {
            throw new Error("version payload is missing");
        }

        const payload_bundle = value.bundle;
        if (payload_bundle == null) {
            throw new Error("bundle payload is missing");
        }

        return {
            kind: "bundle",
            version: fromNapiArtifactVersion(payload_version),
            bundle: fromNapiBundle(payload_bundle),
        };
    }

    if (value.kind === "program") {
        const payload_version = value.version;
        if (payload_version == null) {
            throw new Error("version payload is missing");
        }

        const payload_program = value.program;
        if (payload_program == null) {
            throw new Error("program payload is missing");
        }

        return {
            kind: "program",
            version: fromNapiArtifactVersion(payload_version),
            program: fromNapiProgram(payload_program),
        };
    }

    if (value.kind === "product") {
        const payload_version = value.version;
        if (payload_version == null) {
            throw new Error("version payload is missing");
        }

        const payload_product = value.product;
        if (payload_product == null) {
            throw new Error("product payload is missing");
        }

        return {
            kind: "product",
            version: fromNapiArtifactVersion(payload_version),
            product: fromNapiProduct(payload_product),
        };
    }

    throw new Error("unknown BuildOutput");
}

