/** Convert one Document into the NAPI transport shape. */
export function toNapiDocument(value: Document): Napi.Document {
    if (value.kind === "module") {
        return {
            kind: "module",
            module: toNapiModule(value.module),
        };
    }

    if (value.kind === "text") {
        return {
            kind: "text",
            path: value.path,
            text: value.text,
        };
    }

    throw new Error("unknown Document");
}

