/** Convert one NAPI Content into the public bridge shape. */
export function fromNapiContent(value: Napi.Content): Content {
    if (value.kind === "text") {
        const payload_textContent = value.textContent;
        if (payload_textContent == null) {
            throw new Error("textContent payload is missing");
        }

        return {
            kind: "text",
            content: payload_textContent,
        };
    }

    if (value.kind === "binary") {
        const payload_binaryContent = value.binaryContent;
        if (payload_binaryContent == null) {
            throw new Error("binaryContent payload is missing");
        }

        return {
            kind: "binary",
            content: Uint8Array.from(payload_binaryContent),
        };
    }

    throw new Error("unknown Content");
}

